-poster\">\n          <p class=\"wsy-kicker\">卫疏影 / 18 / 北方初雪</p>\n          <h1>卫疏影</h1>\n          <p class=\"wsy-line\">\n            从县城补课教室到北方大学，她把两封情书藏进录取通知书里，也把那个约定带过了整整一个冬天。\n          </p>\n          <p class=\"wsy-memory\">“从天光乍破，到暮雪白头，缘定三生，不离不弃。”</p>\n          <button class=\"wsy-primary\" type=\"button\" @click=\"enterWorldbookStep\">\n            <span>去见她</span>\n          </button>\n        </div>\n\n        <div v-else-if=\"step === 'worldbook'\" key=\"worldbook\" class=\"wsy-panel wsy-worldbook\">\n          <p class=\"wsy-kicker\">把你最爱的角色带到这场雪里</p>\n          <h2>世界书与角色名</h2>\n          <div class=\"wsy-search\">\n            <input\n              v-model.trim=\"worldbookQuery\"\n              class=\"wsy-input\"\n              placeholder=\"输入完整世界书名或关键词\"\n              spellcheck=\"false\"\n              @keydown.enter.prevent=\"scanWorldbooks\"\n            />\n            <button class=\"wsy-icon-button\" type=\"button\" title=\"扫描\" @click=\"scanWorldbooks\">\n              <span>查找</span>\n            </button>\n          </div>\n\n          <div class=\"wsy-field\">\n            <span class=\"wsy-label\">导入角色名</span>\n            <input\n              v-model.trim=\"characterNameQuery\"\n              class=\"wsy-input\"\n              placeholder=\"输入要导入的角色名\"\n              spellcheck=\"false\"\n              @keydown.enter.prevent=\"scanWorldbooks\"\n            />\n          </div>\n\n          <div class=\"wsy-result-list\" aria-live=\"polite\">\n            <button\n              v-for=\"result in worldbookResults\"\n              :key=\"result.name\"\n              class=\"wsy-result\"\n              :class=\"{ selected: selectedWorldbook?.name === result.name }\"\n              type=\"button\"\n              @click=\"selectWorldbook(result)\"\n            >\n              <span class=\"wsy-result-main\">{{ result.name }}</span>\n              <span class=\"wsy-result-sub\">{{\n                result.characters.length ? result.characters.map(item => item.name).join('、') : '未找到绑定角色卡'\n              }}</span>\n            </button>\n            <div v-if=\"worldbookSearched && worldbookResults.length === 0\" class=\"wsy-empty\">没有找到接近的世界书</div>\n          </div>\n\n          <div v-if=\"selectedWorldbook?.characters.length\" class=\"wsy-character-list\">\n            <button\n              v-for=\"character in selectedWorldbook.characters\"\n              :key=\"character.name\"\n              class=\"wsy-character-chip\"\n              :class=\"{ selected: normalizeText(characterNameQuery) === normalizeText(character.name) }\"\n              type=\"button\"\n              @click=\"selectBoundCharacter(character)\"\n            >\n              {{ character.name }}\n            </button>\n          </div>\n\n          <div v-if=\"flowError\" class=\"wsy-error\">{{ flowError }}</div>\n\n          <button\n            class=\"wsy-primary\"\n            type=\"button\"\n            :disabled=\"!selectedWorldbook || !normalizedCharacterName || isBusy\"\n            @click=\"startMigration\"\n          >\n            <span>{{ isMigrating ? '她正在读这本世界书' : '她是你的最爱，对吗？' }}</span>\n          </button>\n        </div>\n\n        <div v-else-if=\"step === 'migrating'\" key=\"migrating\" class=\"wsy-panel wsy-processing\">\n          <p class=\"wsy-kicker\">角色正在抵达这场雪</p>\n          <h2>{{ selectedWorldbook?.name }}</h2>\n          <div class=\"wsy-process\">\n            <div v-for=\"item in processLogs\" :key=\"item\" class=\"wsy-process-row\">{{ item }}</div>\n            <div v-if=\"!processLogs.length\" class=\"wsy-process-row\">正在准备...</div>\n          </div>\n          <div v-if=\"flowError\" class=\"wsy-error\">{{ flowError }}</div>\n        </div>\n\n        <div v-else-if=\"step === 'ready'\" key=\"ready\" class=\"wsy-panel wsy-ready\">\n          <p class=\"wsy-kicker\">故事即将合流</p>\n          <h2>{{ importedCharacterName }}</h2>\n          <ol class=\"wsy-status\">\n            <li>来源世界书：{{ selectedWorldbook?.name }}</li>\n            <li>导入角色名：{{ importedCharacterName }}</li>\n            <li>写入世界书：{{ targetWorldbook || '卫疏影绑定世界书' }}</li>\n            <li>三人背景、核心人设与二次解释已分层</li>\n            <li v-if=\"migrationResult?.warnings.length\">提示：{{ migrationResult.warnings.join('；') }}</li>\n          </ol>\n          <div v-if=\"coreProfileSummary\" class=\"wsy-summary\">\n            <p class=\"wsy-summary-title\">导入人设摘要</p>\n            <p>{{ coreProfileSummary }}</p>\n          </div>\n          <div v-if=\"flowError\" class=\"wsy-error\">{{ flowError }}</div>\n          <button\n            class=\"wsy-primary\"\n            type=\"button\"\n            :disabled=\"!migrationResult || isBusy\"\n            @click=\"startOpeningGeneration\"\n          >\n            <span>{{ isGeneratingOpening ? '雪正在落下' : '雪开始下了，你准备好了吗？' }}</span>\n          </button>\n        </div>\n\n        <div v-else key=\"opening\" class=\"wsy-panel wsy-opening-preview\">\n          <p class=\"wsy-kicker\">{{ isGeneratingOpening ? '开场白生成中' : '开场白已写入第 0 层' }}</p>\n          <h2>暮雪白头</h2>\n          <div class=\"wsy-process wsy-process-compact\">\n            <div v-for=\"item in processLogs\" :key=\"item\" class=\"wsy-process-row\">{{ item }}</div>\n          </div>\n          <p class=\"wsy-preview-text\">{{ openingText || '雪还在落下。' }}</p>\n          <div v-if=\"flowError\" class=\"wsy-error\">{{ flowError }}</div>\n          <div class=\"wsy-actions\">\n            <button class=\"wsy-secondary\" type=\"button\" :disabled=\"isBusy\" @click=\"step = 'worldbook'\">\n              重选世界书\n            </button>\n            <button\n              class=\"wsy-primary\"\n              type=\"button\"\n              :disabled=\"isBusy || !migrationResult\"\n              @click=\"startOpeningGeneration\"\n            >\n              <span>{{ openingText ? '重新落雪' : '继续生成' }}</span>\n            </button>\n            <button class=\"wsy-secondary\" type=\"button\" :disabled=\"isBusy\" @click=\"step = 'ready'\">\n              <span>返回确认</span>\n            </button>\n          </div>\n        </div>\n      </Transition>\n    </div>\n  </section>\n</template>\n\n<script setup lang=\"ts\">\nimport weishuyingImage from './assets/weishuying-transparent.png?url';\nimport {\n  generateOpening,\n  migrateImportedCharacter,\n  readOpeningState,\n  saveOpeningState,\n  writeMigrationToCurrentCharacterWorldbook,\n  writeOpeningToFirstMessage,\n  type MigrationResult,\n} from './flow';\n\ntype Step = 'poster' | 'worldbook' | 'migrating' | 'ready' | 'opening';\n\ntype BoundCharacter = {\n  name: string;\n  avatar: string | null;\n};\n\ntype WorldbookResult = {\n  name: string;\n  score: number;\n  characters: BoundCharacter[];\n};\n\nconst step = ref<Step>('poster');\nconst worldbookQuery = ref('');\nconst characterNameQuery = ref('');\nconst worldbookResults = ref<WorldbookResult[]>([]);\nconst worldbookSearched = ref(false);\nconst selectedWorldbook = ref<WorldbookResult | null>(null);\nconst importedAvatar = ref<string | null>(null);\nconst migrationResult = ref<MigrationResult | null>(null);\nconst targetWorldbook = ref('');\nconst openingText = ref('');\nconst processLogs = ref<string[]>([]);\nconst flowError = ref('');\nconst isMigrating = ref(false);\nconst isGeneratingOpening = ref(false);\n\nconst isBusy = computed(() => isMigrating.value || isGeneratingOpening.value);\nconst normalizedCharacterName = computed(() => characterNameQuery.value.trim());\nconst selectedBoundCharacter = computed(\n  () =>\n    selectedWorldbook.value?.characters.find(\n      character => normalizeText(character.name) === normalizeText(normalizedCharacterName.value),\n    ) ?? null,\n);\nconst selectedAvatar = computed(\n  () =>\n    resolveCharacterAvatar(migrationResult.value?.character_name ?? normalizedCharacterName.value) ??\n    selectedBoundCharacter.value?.avatar ??\n    importedAvatar.value ??\n    null,\n);\nconst showImportedPortrait = computed(() => step.value === 'ready' || step.value === 'opening');\nconst portraitImage = computed(() => (showImportedPortrait.value && selectedAvatar.value) ? selectedAvatar.value : weishuyingImage);\nconst portraitAlt = computed(() => showImportedPortrait.value ? importedCharacterName.value : '卫疏影');\nconst importedCharacterName = computed(\n  () => migrationResult.value?.character_name || normalizedCharacterName.value || '导入角色',\n);\nconst coreProfileSummary = computed(() => {\n  const result = migrationResult.value;\n  if (!result) return '';\n  return result.core_profile_summary || summarizeText(result.core_profile, 180);\n});\n\nfunction normalizeText(text: string): string {\n  return text.toLowerCase().replace(/[\\s\"'“”‘’《》【】[\\]（）()_\\-—·.。,:：;；/\\\\|]+/g, '');\n}\n\nfunction scoreWorldbookName(name: string, query: string): number {\n  const normalizedName = normalizeText(name);\n  const normalizedQuery = normalizeText(query);\n  if (!normalizedQuery) return 1;\n  if (normalizedName === normalizedQuery) return 100;\n  if (normalizedName.includes(normalizedQuery)) return 80 + Math.min(19, normalizedQuery.length);\n  if (normalizedQuery.includes(normalizedName)) return 70;\n  const chars = [...new Set(normalizedQuery.split(''))];\n  const hits = chars.filter(char => normalizedName.includes(char)).length;\n  return (hits / Math.max(1, chars.length)) * 60;\n}\n\nfunction scoreCharacterNames(characters: BoundCharacter[], query: string): number {\n  const normalizedQuery = normalizeText(query);\n  if (!normalizedQuery) return 0;\n  return Math.max(\n    0,\n    ...characters.map(character => {\n      const normalizedName = normalizeText(character.name);\n      if (normalizedName === normalizedQuery) return 100;\n      if (normalizedName.includes(normalizedQuery)) return 80 + Math.min(19, normalizedQuery.length);\n      if (normalizedQuery.includes(normalizedName)) return 70;\n      const chars = [...new Set(normalizedQuery.split(''))];\n      const hits = chars.filter(char => normalizedName.includes(char)).length;\n      return (hits / Math.max(1, chars.length)) * 60;\n    }),\n  );\n}\n\nfunction summarizeText(text: string, maxLength: number): string {\n  const normalized = text.replace(/\\s+/g, ' ').trim();\n  if (normalized.length <= maxLength) return normalized;\n  return `${normalized.slice(0, maxLength)}...`;\n}\n\nfunction getCharacterCardNames(): string[] {\n  try {\n    return getCharacterNames();\n  } catch {\n    return (SillyTavern.characters ?? []).map(character => character.name).filter(Boolean);\n  }\n}\n\nfunction resolveCharacterAvatar(characterName: string): string | null {\n  const normalizedName = normalizeText(characterName);\n  if (!normalizedName) return null;\n\n  const exactName = getCharacterCardNames().find(name => normalizeText(name) === normalizedName);\n  const candidates = [...new Set([exactName, characterName].filter((name): name is string => Boolean(name)))];\n  for (const candidate of candidates) {\n    try {\n      const avatar = getCharAvatarPath(candidate);\n      if (avatar) return avatar;\n    } catch {\n      // The typed name may be an alias that has no matching local character card.\n    }\n  }\n  return null;\n}\n\nfunction findBoundCharacters(worldbookName: string): BoundCharacter[] {\n  const characters = SillyTavern.characters ?? [];\n  return characters\n    .filter(character => {\n      try {\n        const bindings = getCharWorldbookNames(character.name);\n        return bindings.primary === worldbookName || bindings.additional.includes(worldbookName);\n      } catch {\n        return false;\n      }\n    })\n    .map(character => ({\n      name: character.name,\n      avatar: getCharAvatarPath(character.name),\n    }));\n}\n\nfunction makeWorldbookResult(name: string): WorldbookResult {\n  return {\n    name,\n    score: 100,\n    characters: findBoundCharacters(name),\n  };\n}\n\nfunction logProcess(message: string): void {\n  processLogs.value = [...processLogs.value, message].slice(-6);\n}\n\nfunction getErrorMessage(error: unknown): string {\n  return error instanceof Error ? error.message : String(error);\n}\n\nfunction restoreState(): void {\n  const saved = readOpeningState();\n  if (saved.source_worldbook) {\n    selectedWorldbook.value = makeWorldbookResult(saved.source_worldbook);\n    worldbookQuery.value = saved.source_worldbook;\n    worldbookResults.value = [selectedWorldbook.value];\n    worldbookSearched.value = true;\n  }\n  characterNameQuery.value = saved.requested_character_name ?? saved.imported_character_name ?? '';\n  importedAvatar.value = saved.imported_avatar ?? null;\n  migrationResult.value = saved.migration_result ?? null;\n  targetWorldbook.value = saved.target_worldbook ?? '';\n  openingText.value = saved.opening_text ?? '';\n  if (openingText.value) {\n    step.value = 'opening';\n  } else if (migrationResult.value) {\n    step.value = 'ready';\n  }\n}\n\nfunction enterWorldbookStep(): void {\n  step.value = 'worldbook';\n  if (!worldbookSearched.value) {\n    scanWorldbooks();\n  }\n}\n\nfunction scanWorldbooks(): void {\n  worldbookSearched.value = true;\n  selectedWorldbook.value = null;\n  importedAvatar.value = null;\n  const query = worldbookQuery.value;\n  const characterQuery = characterNameQuery.value;\n  worldbookResults.value = getWorldbookNames()\n    .map(name => {\n      const characters = findBoundCharacters(name);\n      return {\n        name,\n        score: scoreWorldbookName(name, query) + scoreCharacterNames(characters, characterQuery),\n        characters,\n      };\n    })\n    .filter(result => result.score >= (query || characterQuery ? 24 : 1))\n    .sort((a, b) => b.score - a.score || a.name.localeCompare(b.name, 'zh-Hans-CN'))\n    .slice(0, 8);\n}\n\nfunction selectWorldbook(result: WorldbookResult): void {\n  selectedWorldbook.value = result;\n  if (result.characters.length === 1 && !normalizedCharacterName.value) {\n    characterNameQuery.value = result.characters[0].name;\n    importedAvatar.value = resolveCharacterAvatar(result.characters[0].name) ?? result.characters[0].avatar;\n    return;\n  }\n  importedAvatar.value = resolveCharacterAvatar(normalizedCharacterName.value) ?? selectedBoundCharacter.value?.avatar ?? null;\n}\n\nfunction selectBoundCharacter(character: BoundCharacter): void {\n  characterNameQuery.value = character.name;\n  importedAvatar.value = resolveCharacterAvatar(character.name) ?? character.avatar;\n}\n\nwatch(characterNameQuery, () => {\n  importedAvatar.value = resolveCharacterAvatar(normalizedCharacterName.value) ?? selectedBoundCharacter.value?.avatar ?? null;\n});\n\nasync function startMigration(): Promise<void> {\n  if (!selectedWorldbook.value) return;\n  const sourceWorldbook = selectedWorldbook.value.name;\n  const requestedCharacterName = normalizedCharacterName.value;\n  if (!requestedCharacterName) {\n    flowError.value = '请先填写要导入的角色名';\n    return;\n  }\n  isMigrating.value = true;\n  flowError.value = '';\n  processLogs.value = [];\n  openingText.value = '';\n  migrationResult.value = null;\n  targetWorldbook.value = '';\n  step.value = 'migrating';\n  saveOpeningState({\n    source_worldbook: sourceWorldbook,\n    requested_character_name: requestedCharacterName,\n    imported_character_name: requestedCharacterName,\n    imported_avatar: selectedAvatar.value,\n    bound_card_name: selectedBoundCharacter.value?.name || undefined,\n    opening_text: '',\n  });\n\n  try {\n    logProcess('正在读取世界书条目');\n    logProcess(`正在定位 ${requestedCharacterName} 的人设`);\n    const result = await migrateImportedCharacter(sourceWorldbook, requestedCharacterName);\n    migrationResult.value = result;\n    importedAvatar.value = resolveCharacterAvatar(result.character_name) ?? selectedAvatar.value;\n    logProcess(`已完成 ${result.character_name} 的人设移植`);\n\n    logProcess('正在写入卫疏影绑定世界书');\n    const writeResult = await writeMigrationToCurrentCharacterWorldbook(sourceWorldbook, result);\n    targetWorldbook.value = writeResult.targetWorldbook;\n    logProcess(`已写入 ${writeResult.entryUids.length} 个世界书条目`);\n    saveOpeningState({\n      source_worldbook: sourceWorldbook,\n      requested_character_name: requestedCharacterName,\n      imported_character_name: result.character_name,\n      imported_avatar: selectedAvatar.value,\n      target_worldbook: writeResult.targetWorldbook,\n      migration_result: result,\n      migration_entry_uids: writeResult.entryUids,\n      relationship_background: writeResult.relationshipBackground,\n    });\n    step.value = 'ready';\n  } catch (error) {\n    flowError.value = `移植失败：${getErrorMessage(error)}`;\n    step.value = 'worldbook';\n  } finally {\n    isMigrating.value = false;\n  }\n}\n\nasync function startOpeningGeneration(): Promise<void> {\n  if (!selectedWorldbook.value || !migrationResult.value) return;\n  isGeneratingOpening.value = true;\n  flowError.value = '';\n  processLogs.value = [];\n  openingText.value = '';\n  step.value = 'opening';\n\n  try {\n    logProcess('正在调用模型写开场白');\n    const finalOpening = await generateOpening(migrationResult.value, selectedWorldbook.value.name, text => {\n      openingText.value = text;\n    });\n    openingText.value = finalOpening;\n    saveOpeningState({ opening_text: finalOpening });\n    logProcess('正在写入第 0 层');\n    await writeOpeningToFirstMessage(finalOpening);\n    saveOpeningState({ opening_text: finalOpening });\n    logProcess('第 0 层已更新，即将关闭脚本');\n    window.setTimeout(() => {\n      window.dispatchEvent(new Event('pagehide'));\n    }, 1500);\n  } catch (error) {\n    flowError.value = `开场生成失败：${getErrorMessage(error)}`;\n  } finally {\n    isGeneratingOpening.value = false;\n  }\n}\n\nonMounted(restoreState);\n</script>\n\n<style scoped>\n.wsy-opening {\n  --wsy-ink: #f6f2ea;\n  --wsy-paper: rgba(246, 242, 234, 0.08);\n  --wsy-muted: rgba(246, 242, 234, 0.68);\n  --wsy-faint: rgba(246, 242, 234, 0.42);\n  --wsy-line: rgba(246, 242, 234, 0.14);\n  --wsy-black: #08090b;\n  --wsy-red: #9f2f32;\n  --wsy-red-soft: rgba(15