import { teleportStyle } from '@util/script';
import App from './App.vue';
const HOST_ID = 'weishuying-opening-host';
let app = null;
let $host = null;
let $hiddenSource = null;
let originalDisplay;
let styleDestroy = null;
function findOpeningMessage() {
    return $('#chat').children(".mes[mesid='0']").first();
}
function unmountOpening() {
    if (app) {
        app.unmount();
        app = null;
    }
    $host?.remove();
    $host = null;
    if ($hiddenSource) {
        $hiddenSource.css('display', originalDisplay ?? '');
        $hiddenSource = null;
        originalDisplay = undefined;
    }
    styleDestroy?.();
    styleDestroy = null;
}
function mountOpening() {
    const $message = findOpeningMessage();
    if ($message.length === 0) {
        return;
    }
    const $messageText = $message.find('.mes_text').first();
    if ($messageText.length === 0) {
        return;
    }
    if ($message.find(`#${HOST_ID}`).length > 0) {
        return;
    }
    unmountOpening();
    originalDisplay = $messageText.css('display');
    $messageText.css('display', 'none');
    $hiddenSource = $messageText;
    $host = $('<div>')
        .attr({
        id: HOST_ID,
        script_id: getScriptId(),
    })
        .insertAfter($messageText);
    styleDestroy = teleportStyle().destroy;
    app = createApp(App).use(createPinia());
    app.mount($host[0]);
}
function scheduleMount() {
    window.setTimeout(errorCatched(mountOpening), 150);
}
$(() => {
    scheduleMount();
    eventOn('chatLoaded', () => {
        unmountOpening();
        scheduleMount();
    });
    eventOn(tavern_events.CHAT_CHANGED, () => {
        unmountOpening();
        scheduleMount();
    });
    eventOn(tavern_events.CHARACTER_MESSAGE_RENDERED, messageId => {
        if (messageId === 0) {
            unmountOpening();
            scheduleMount();
        }
    });
    eventOn(tavern_events.MESSAGE_EDITED, messageId => {
        if (messageId === 0) {
            unmountOpening();
            scheduleMount();
        }
    });
    $(window).on('pagehide', unmountOpening);
});
