const STATE_KEY = '卫疏影开局前端';
const FLOW_VERSION = 4;
const MAX_SERIALIZED_WORLDBOOK_LENGTH = 90000;

export type MigrationResult = {
  character_name: string;
  core_profile_summary: string;
  secondary_profile: string;
  core_profile: string;
  speech_and_behavior: string;
  relationship_patterns: string;
  retained_minimal_worldview: string;
  removed_worldview_note: string;
  secondary_interpretation: string;
  opening_brief: string;
  limits: string;
  warnings: string[];
};

export type OpeningFlowState = {
  version: number;
  source_worldbook?: string;
  requested_character_name?: string;
  imported_character_name?: string;
  imported_avatar?: string | null;
  bound_card_name?: string;
  target_worldbook?: string;
  migration_result?: MigrationResult;
  migration_entry_uids?: number[];
  relationship_background?: string;
  opening_text?: string;
  updated_at?: string;
};

type SerializedWorldbook = {
  text: string;
  entry_count: number;
  truncated: boolean;
};

function getString(value: unknown, fallback = ''): string {
  return typeof value === 'string' ? value.trim() : fallback;
}

function normalizeWarnings(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  return value.map(item => getString(item)).filter(Boolean);
}

function summarizeText(text: string, maxLength = 180): string {
  const normalized = text.replace(/\s+/g, ' ').trim();
  if (normalized.length <= maxLength) return normalized;
  return `${normalized.slice(0, maxLength)}...`;
}

function stripBootstrapMetaDirectives(text: string): string {
  return text
    .split('\n')
    .filter(line => {
      const normalizedLine = line.trim().replace(/^#{1,6}\s*/, '');
      return !/^【?\s*卫疏影开局/.test(normalizedLine);
    })
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function stripOpeningScaffold(text: string): string {
  return stripBootstrapMetaDirectives(text)
    .replace(/^```(?:text|markdown)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .replace(/^(?:正式)?开场白[：:]\s*/i, '')
    .trim();
}

function makeCharacterBlockId(characterName: string): string {
  return `${characterName.replace(/[<>\s]/g, '') || '导入角色'}_id2`;
}

function wrapAsId2Block(content: string, characterName: string, fallbackTitle: string): string {
  const trimmed = stripBootstrapMetaDirectives(content);
  if (/<[^>\n]+_id2>/i.test(trimmed) && /<\/[^>\n]+_id2>/i.test(trimmed)) {
    return trimmed;
  }

  const blockId = makeCharacterBlockId(characterName);
  const body = trimmed || fallbackTitle;
  return [`<${blockId}>`, body, `</${blockId}>`].join('\n');
}

function normalizeMigrationResult(value: Record<string, unknown>, fallbackName: string): MigrationResult {
  const coreProfile = getString(value.core_profile);
  const characterName = getString(value.character_name, fallbackName) || fallbackName;
  const secondaryProfile = getString(value.secondary_profile);
  const secondaryInterpretation = getString(value.secondary_interpretation, secondaryProfile);
  return {
    character_name: characterName,
    core_profile_summary: getString(value.core_profile_summary) || summarizeText(coreProfile),
    secondary_profile: wrapAsId2Block(
      secondaryProfile || secondaryInterpretation,
      characterName,
      `——对${characterName}的理解与思考——`,
    ),
    core_profile: wrapAsId2Block(coreProfile, characterName, '角色档案:'),
    speech_and_behavior: getString(value.speech_and_behavior),
    relationship_patterns: getString(value.relationship_patterns),
    retained_minimal_worldview: getString(value.retained_minimal_worldview, '无必须保留的额外世界观。'),
    removed_worldview_note: getString(value.removed_worldview_note, '已删除与本卡无关的原世界观、势力和剧情线。'),
    secondary_interpretation: secondaryInterpretation || '无单独作者二次解释。',
    opening_brief: getString(value.opening_brief),
    limits: getString(value.limits),
    warnings: normalizeWarnings(value.warnings),
  };
}

function stripJsonFence(text: string): string {
  return text
    .trim()
    .replace(/^```(?:json)?/i, '')
    .replace(/```$/i, '')
    .trim();
}

function extractJsonObject(text: string): Record<string, unknown> {
  const stripped = stripJsonFence(text);
  const start = stripped.indexOf('{');
  const end = stripped.lastIndexOf('}');
  if (start < 0 || end <= start) {
    throw new Error('AI 没有返回 JSON 对象');
  }
  return JSON.parse(stripped.slice(start, end + 1)) as Record<string, unknown>;
}

function serializeEntry(entry: WorldbookEntry, index: number): string {
  return [
    `#${index + 1} ${entry.name || `未命名条目${index + 1}`}`,
    `enabled: ${entry.enabled}`,
    `strategy: ${entry.strategy.type}`,
    `position: ${entry.position.type}, role=${entry.position.role}, depth=${entry.position.depth}, order=${entry.position.order}`,
    `keys: ${entry.strategy.keys.map(String).join(' / ') || '无'}`,
    'content:',
    entry.content || '',
  ].join('\n');
}

function serializeWorldbook(entries: WorldbookEntry[]): SerializedWorldbook {
  let text = '';
  let truncated = false;
  for (const [index, entry] of entries.entries()) {
    const part = `${serializeEntry(entry, index)}\n\n---\n\n`;
    if (text.length + part.length > MAX_SERIALIZED_WORLDBOOK_LENGTH) {
      truncated = true;
      text += `\n[后续 ${entries.length - index} 个条目因上下文长度被截断；请根据已读取内容优先保留角色本人信息。]\n`;
      break;
    }
    text += part;
  }
  return { text, entry_count: entries.length, truncated };
}

export function readOpeningState(): OpeningFlowState {
  try {
    const variables = getVariables({ type: 'chat' });
    const value = variables[STATE_KEY];
    if (typeof value === 'object' && value !== null) {
      return value as OpeningFlowState;
    }
  } catch {
    // Chat variables may be unavailable before a chat is fully opened.
  }
  return { version: FLOW_VERSION };
}

export function saveOpeningState(patch: Partial<OpeningFlowState>): OpeningFlowState {
  const next: OpeningFlowState = {
    ...readOpeningState(),
    ...patch,
    version: FLOW_VERSION,
    updated_at: new Date().toISOString(),
  };
  updateVariablesWith(
    variables => {
      variables[STATE_KEY] = next;
      return variables;
    },
    { type: 'chat' },
  );
  return next;
}

