export async function ensureTargetWorldbook(): Promise<string> {
  const charWorldbook = getCharWorldbookNames('current');
  const worldbookNames = getWorldbookNames();
  const worldbookNameSet = new Set(worldbookNames);
  const currentName = getCurrentCharacterName() || getCharData('current')?.name || '卫疏影';
  const namedTarget = [currentName, '卫疏影'].find(name => worldbookNameSet.has(name));
  const primaryIsOldGeneratedTarget =
    charWorldbook.primary === `${currentName}_开局导入` || charWorldbook.primary === '卫疏影_开局导入';

  if (
    charWorldbook.primary &&
    worldbookNameSet.has(charWorldbook.primary) &&
    !(primaryIsOldGeneratedTarget && namedTarget)
  ) {
    return charWorldbook.primary;
  }

  if (namedTarget) {
    await rebindCharWorldbooks('current', {
      primary: namedTarget,
      additional: charWorldbook.additional.filter(name => name !== namedTarget),
    });
    return namedTarget;
  }

  const additional = charWorldbook.additional.find(name => worldbookNameSet.has(name));
  if (additional) return additional;

  const target = currentName;
  await createWorldbook(target, []);
  await rebindCharWorldbooks('current', { primary: target, additional: [] });
  return target;
}

function buildCoreEntryContent(result: MigrationResult): string {
  return wrapAsId2Block(result.core_profile, result.character_name, '角色档案:');
}

function buildSecondaryEntryContent(result: MigrationResult): string {
  return wrapAsId2Block(
    result.secondary_profile || result.secondary_interpretation,
    result.character_name,
    `——对${result.character_name}的理解与思考——`,
  );
}

export function buildRelationshipBackground(sourceWorldbook: string, result: MigrationResult): string {
  return stripBootstrapMetaDirectives(
    relationshipTemplate
      .replaceAll('__IMPORTED_CHARACTER_NAME__', result.character_name)
      .replaceAll('__SOURCE_WORLDBOOK__', sourceWorldbook),
  );
}

function getGeneratedEntryName(result: MigrationResult, type: 'relationship' | 'core' | 'secondary'): string {
  if (type === 'relationship') return `${result.character_name}-三人关系背景`;
  if (type === 'core') return `${result.character_name}-核心人设`;
  return `${result.character_name}-二次解释`;
}

function getLegacyGeneratedEntryName(result: MigrationResult, type: 'relationship' | 'core' | 'secondary'): string {
  if (type === 'relationship') return `卫疏影开局导入-${result.character_name}-三人关系背景`;
  if (type === 'core') return `卫疏影开局导入-${result.character_name}-核心人设`;
  return `卫疏影开局导入-${result.character_name}-二次解释`;
}

function isLegacyBootstrapMetaEntry(entryName: string, result: MigrationResult): boolean {
  if (!entryName.includes('卫疏影开局导入')) return false;
  if (!entryName.includes(result.character_name) && !entryName.includes('导入角色')) return false;
  return ['三人关系背景', '核心人设', '二次解释'].some(keyword => entryName.includes(keyword));
}

function makeGeneratedEntry(
  sourceWorldbook: string,
  result: MigrationResult,
  type: 'relationship' | 'core' | 'secondary',
): PartialDeep<WorldbookEntry> {
  const isRelationship = type === 'relationship';
  const isCore = type === 'core';
  return {
    name: getGeneratedEntryName(result, type),
    enabled: true,
    strategy: {
      type: 'constant',
      keys: [],
      keys_secondary: { logic: 'and_any', keys: [] },
      scan_depth: 'same_as_global',
    },
    position:
      isRelationship || isCore
        ? { type: 'before_character_definition', role: 'system', depth: 0, order: isRelationship ? 1 : 100 }
        : { type: 'at_depth', role: 'system', depth: 0, order: 1 },
    content: isRelationship
      ? buildRelationshipBackground(sourceWorldbook, result)
      : isCore
        ? buildCoreEntryContent(result)
        : buildSecondaryEntryContent(result),
    probability: 100,
    recursion: {
      prevent_incoming: true,
      prevent_outgoing: true,
      delay_until: null,
    },
    effect: {
      sticky: null,
      cooldown: null,
      delay: null,
    },
    extra: {
      weishuying_bootstrap: {
        version: FLOW_VERSION,
        type,
        source_worldbook: sourceWorldbook,
        character_name: result.character_name,
      },
    },
  };
}

export async function writeMigrationToCurrentCharacterWorldbook(
  sourceWorldbook: string,
  result: MigrationResult,
): Promise<{ targetWorldbook: string; entryUids: number[]; relationshipBackground: string }> {
  const targetWorldbook = await ensureTargetWorldbook();
  const generatedNames = new Set(
    (['relationship', 'core', 'secondary'] as const).flatMap(type => [
      getGeneratedEntryName(result, type),
      getLegacyGeneratedEntryName(result, type),
    ]),
  );
  await updateWorldbookWith(
    targetWorldbook,
    worldbook =>
      worldbook.filter(entry => {
        const marker = entry.extra?.weishuying_bootstrap;
        return !marker && !generatedNames.has(entry.name) && !isLegacyBootstrapMetaEntry(entry.name, result);
      }),
    { render: 'debounced' },
  );
  const { new_entries } = await createWorldbookEntries(
    targetWorldbook,
    [
      makeGeneratedEntry(sourceWorldbook, result, 'relationship'),
      makeGeneratedEntry(sourceWorldbook, result, 'core'),
      makeGeneratedEntry(sourceWorldbook, result, 'secondary'),
    ],
    { render: 'immediate' },
  );
  return {
    targetWorldbook,
    entryUids: new_entries.map(entry => entry.uid),
    relationshipBackground: buildRelationshipBackground(sourceWorldbook, result),
  };
}

function buildOpeningImportedProfile(result: MigrationResult): string {
  return [
    `导入角色名：${result.character_name}`,
    result.core_profile_summary && `核心摘要：${result.core_profile_summary}`,
    result.opening_brief && `开场参考：${result.opening_brief}`,
    result.speech_and_behavior && `说话与行为：${result.speech_and_behavior}`,
    result.relationship_patterns && `亲密关系模式：${result.relationship_patterns}`,
    result.retained_minimal_worldview && `必要保留世界观：${result.retained_minimal_worldview}`,
    result.limits && `边界：${result.limits}`,
    '二次解释：',
    buildSecondaryEntryContent(result),
    '核心人设：',
    buildCoreEntryContent(result),
  ]
    .filter((part): part is string => Boolean(part))
    .join('\n');
}

export async function generateOpening(
  result: MigrationResult,
  sourceWorldbook: string,
  onStream: (text: string) => void,
): Promise<string> {
  const generationId = `weishuying-opening-${Date.now()}`;
  const listener = eventOn(iframe_events.STREAM_TOKEN_RECEIVED_FULLY, (text, id) => {
    if (id === generationId) {
      onStream(stripOpeningScaffold(text));
    }
  });
  try {
    const finalText = await generateRaw({
      generation_id: generationId,
      should_stream: true,
      should_silence: false,
      max_chat_history: 0,
      ordered_prompts: [
        {
          role: 'system',
          content: [
            '你是卫疏影角色卡的开场白写作助手。',
            '你要写正式开场白纯文本，不要标题，不要 Markdown，不要解释。',
            '必须让卫疏影、{{user}}、导入角色三人都真实成立；不替{{user}}解释背叛原因，不替{{user}}做选择。',
            '禁止输出世界书条目标题、JSON 字段名、迁移报告或任何“卫疏影开局导入”类元指令。',
            '结尾必须留下{{user}}可以行动的空间。',
          ].join('\n'),
        },
        {
          role: 'user',
          content: [
            '【卫疏影角色基础】',
            characterBase,
            '',
            '【卫疏影角色规则】',
            characterRules,
            '',
            '【卫疏影调色盘人设】',
            paletteProfile,
            '',
            '【卫疏影混色人设】',
            mixedProfile,
            '',
            '【开场核心要求】',
            openingCore,
            '',
            '【三人关系背景（已写入世界书）】',
            buildRelationshipBackground(sourceWorldbook, result),
            '',
            '【导入角色来源】',
            sourceWorldbook,
            '',
            '【导入角色移植结果】',
            buildOpeningImportedProfile(result),
            '',
            '请根据以上内容生成正式开场白。必须保留“从天光乍破，到暮雪白头”与“如果重来……我不要再喜欢你了”的等价核心，不要把导入角色写成恶毒情敌。',
          ].join('\n'),
        },
      ],
    });
    const opening = stripOpeningScaffold(finalText);
    onStream(opening);
    return opening;
  } finally {
    listener.stop();
  }
}

export async function writeOpeningToFirstMessage(openingText: string): Promise<void> {
  const message = stripOpeningScaffold(openingText);
  const current = getChatMessages(0);
  if (current.length > 0) {
    await setChatMessages(
      [{ message_id: 0, role: 'assistant', name: getCharData('current')?.name || '卫疏影', message }],
      { refresh: 'affected' },
    );
    return;
  }
  await createChatMessages(
    [
      {
        role: 'assistant',
        name: getCharData('current')?.name || '卫疏影',
        message,
      },
    ],
    { insert_before: 'end', refresh: 'affected' },
  );
}
